(function(root){
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=v=>Number.isFinite(v)?v.toFixed(2):'未知';
function render(bars,label,status='sample'){
let section=$('clue-extra');if(!section){section=document.createElement('div');section.id='clue-extra';section.innerHTML='<h3 class="volume-heading">成交量</h3><svg id="volume-chart" viewBox="0 0 760 110" role="img" aria-label="每日成交量"></svg><p id="volume-note" class="meta"></p><section class="latest-clue"><div class="clue-heading"><h3 id="clue-title">最近一次单股量价线索</h3><label>查看标记<select id="clue-select" aria-label="选择价格线索日期"></select></label></div><p id="clue-explanation"></p><p id="clue-current"></p><p class="meta">仅核对单股量价，未加入 SPY / SOXX 环境条件；与下方技术候选口径不同。按当前价格规则回看历史，仅使用当日及此前数据。圆点标记条件开始满足的日期，连续满足不重复标记。不是当时保存的买点，也不是完整策略回测。</p></section>';$('chart').after(section);}
const svg=$('chart'),vol=$('volume-chart'),select=$('clue-select');section.hidden=!bars.length;
if(!bars.length){svg.innerHTML='<text x="380" y="125" text-anchor="middle">'+esc(label||'暂无可用历史数据')+'</text>';vol.innerHTML='';select.onchange=null;return;}
const calculated=PriceClues.analyze(bars),points=calculated.points,start=Math.max(0,points.length-100),shown=points.slice(start),events=status==='sample'?[]:calculated.events,latest=events.at(-1),visible=events.filter(e=>e.index>=start),choices=visible.length?visible:latest?[latest]:[];
select.innerHTML=choices.length?choices.map((e,i)=>`<option value="${i}">${esc(e.date)} · ${e.name}${e.index<start?'（图外）':''}</option>`).join(''):'<option>暂无可验证的标记</option>';select.disabled=!choices.length;select.value=String(choices.length-1);
const vals=shown.flatMap(p=>[p.c,p.ma50]).filter(Number.isFinite),lo=Math.min(...vals)*.97,hi=Math.max(...vals)*1.03,x=i=>50+(i-start)*660/Math.max(1,shown.length-1),y=v=>214-(v-lo)/(hi-lo||1)*170,path=key=>shown.map((p,j)=>Number.isFinite(p[key])?`${j===0||!Number.isFinite(shown[j-1][key])?'M':'L'}${x(p.index).toFixed(1)},${y(p[key]).toFixed(1)}`:'').join(' ');
let base='<title>'+esc(label)+'</title>';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;base+=`<line x1="50" x2="718" y1="${y(v)}" y2="${y(v)}" stroke="#e4ece8"/><text x="2" y="${y(v)+4}">${v.toFixed(1)}</text>`;}base+=`<path d="${path('c')}" fill="none" stroke="#267b63" stroke-width="2.5"/><path d="${path('ma50')}" fill="none" stroke="#b98a40" stroke-width="1.8"/><text x="50" y="18">收盘 / 50日均价</text><text x="300" y="18">● 企稳（绿） · 转强（蓝）</text><text x="50" y="248">${esc(shown[0].date)}</text><text x="625" y="248">${esc(shown.at(-1).date)}</text>`;
const maxV=Math.max(1,...shown.map(p=>Number.isFinite(p.v)?p.v:0)),width=Math.max(2,Math.min(10,600/shown.length)),volumes=shown.map(p=>Number.isFinite(p.v)&&p.v>=0?`<rect x="${x(p.index)-width/2}" y="${88-p.v/maxV*64}" width="${width}" height="${p.v/maxV*64}" fill="#8bb8a5"><title>${esc(p.date)}：${p.v.toLocaleString('zh-CN')} 股</title></rect>`:'').join('');
$('volume-note').textContent=shown.some(p=>Number.isFinite(p.v))?'柱高表示每日成交股数；空缺表示来源未提供。最高 '+Math.round(maxV).toLocaleString('zh-CN')+' 股。':'这段历史未提供成交量，不能验证量能条件。';
function choose(){const e=choices[Number(select.value)];$('clue-title').textContent=e&&e!==latest?'所选日期的单股量价线索':'最近一次单股量价线索';svg.innerHTML=base+visible.map(v=>`<circle cx="${x(v.index)}" cy="${y(v.c)}" r="${e===v?6:3.5}" fill="${v.type==='dip'?'#176b5d':'#377aba'}" stroke="white" stroke-width="1.5"><title>${esc(v.date)} ${v.name}</title></circle>`).join('');vol.innerHTML='<title>成交量，与上方日期对齐</title>'+volumes+(e&&e.index>=start?`<line x1="${x(e.index)}" x2="${x(e.index)}" y1="12" y2="90" stroke="#377aba" stroke-dasharray="3 3"/>`:'');
if(!e){$('clue-explanation').textContent=status==='sample'?'示例未提供可验证的完整日线，不生成历史线索。':'当前返回的历史中，没有可验证的新价格线索。';$('clue-current').textContent='历史不足、成交量缺失或大幅价格跳变的区间，不标记线索。';return;}
$('clue-explanation').textContent=e.date+' · '+e.name+'。'+(e.type==='dip'?`距60日高点回撤 ${n(e.drawdown)}%（需≤−15%）；收盘高于前日高点 ${n(e.stabilize)}%（需>0%）；量比 ${n(e.volume)} 倍（需≥1）。`:`高于50日均价 ${n(e.stock)}%（需>0%且≤10%）；量比 ${n(e.volume)} 倍（需≥1.2）。`)+(e.index<start?'此标记早于当前图表窗口。':'');const last=points.at(-1),key=e.type==='dip'?'dip':'trend';$('clue-current').textContent=status!=='ok'?'当前日线过期、缓存或待核实，暂不能确认这条线索是否仍成立。':!last[key+'Known']?'最新日线缺少必要证据，暂不能确认是否仍成立。':`${last.date}：`+(last[key]?'这类价格条件仍满足。':'这类价格条件已不再满足。')+' 尚需核实市场环境、估值与经营情况。';}
select.onchange=choose;choose();
}
root.ClueChart={render};
})(globalThis);
